Plan:
Copy the workbook, read cached values from Sheet1, and convert each A2:A19 entry to a date-only datetime by truncating any `T...Z` time portion. Write the resulting datetimes into the answer cells with a short date number format. Save the workbook to `OUT`.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def to_date_only(value):
    if value is None:
        return None

    if isinstance(value, datetime):
        return datetime(value.year, value.month, value.day)

    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)

    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None

        if "T" in s:
            s = s.split("T", 1)[0]
        elif " " in s:
            s = s.split(" ", 1)[0]

        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d", "%d/%m/%Y"):
            try:
                d = datetime.strptime(s, fmt)
                return datetime(d.year, d.month, d.day)
            except ValueError:
                pass

        try:
            d = datetime.strptime(s[:10], "%Y-%m-%d")
            return datetime(d.year, d.month, d.day)
        except Exception:
            return None

    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            from openpyxl.utils.datetime import from_excel
            dt = from_excel(value)
            return datetime(dt.year, dt.month, dt.day)
        except Exception:
            return None

    return None

converted = 0
for row in range(2, 20):
    src = vws.cell(row=row, column=1).value
    dst = ws.cell(row=row, column=1)

    d = to_date_only(src)
    if d is not None:
        dst.value = d
        dst.number_format = "m/d/yyyy"
        converted += 1
    else:
        dst.value = None

print("converted:", converted)
print("sample:", [ws.cell(row=r, column=1).value for r in range(2, 6)])

wb.save(OUT)
